import unittest
from config import parse_bool
from service import enabled
class Contract(unittest.TestCase):
 def test_valid(self):
  self.assertIs(parse_bool("true"),True)
  self.assertIs(parse_bool("false"),False)
  self.assertIs(enabled({"enabled":"false"}),False)
 def test_invalid(self):
  for x in ["", "TRUE", "0", None]:
   with self.assertRaises(ValueError): parse_bool(x)
  with self.assertRaises(ValueError): enabled({"enabled":"yes"})

